document.getElementById('repoSearchBtn').addEventListener('click', async () => {
  const q = document.getElementById('repoQuery').value.trim();
  if(!q) return;
  const searchUrl = `https://portalrepository.com/?s=${encodeURIComponent(q)}`;
  const frame = document.getElementById('repoFrame');
  try{
    // Attempt to point the embedded frame at the query; most sites block
    // cross-origin embedding, so this is a best-effort — the visible
    // fallback note and the "Repository ↗" button always remain available.
    frame.src = searchUrl;
  }catch(err){
    window.open(searchUrl, '_blank', 'noopener');
  }
  // Always also give the option of a real tab, since embedding is not guaranteed.
});

