document.getElementById('repoSearchBtn').addEventListener('click', () => {
  const q = document.getElementById('repoQuery').value.trim();
  if(!q) return;
  // Embedding is confirmed blocked (x-frame-options: sameorigin), so this
  // opens a real tab rather than pretending an in-app frame will work.
  const searchUrl = `https://portalrepository.com/?s=${encodeURIComponent(q)}`;
  window.open(searchUrl, '_blank', 'noopener');
});

